 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = sorted({v for row in grid for v in row if v})

    def components(color):
        seen, objs = set(), []
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or (r, c) in seen:
                    continue
                todo, cells = [(r, c)], []
                seen.add((r, c))
                while todo:
                    y, x = todo.pop()
                    cells.append((y, x))
                    for p in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                        py, px = p
                        if 0 <= py < h and 0 <= px < w and grid[py][px] == color and p not in seen:
                            seen.add(p)
                            todo.append(p)
                objs.append(cells)
        return objs

    objects = {c: components(c) for c in colors}
    # Sort each color's two objects by area, so equal ranks are placed together.
    assert all(len(objects[c]) == 2 for c in colors)
    ranked = {c: sorted(objects[c], key=len) for c in colors}
    groups = []
    for rank in range(2):
        group = [(ranked[c][rank], c) for c in colors]
        group.sort(key=lambda item: (len(item[0]), item[1]))
        groups.append(group)

    def bbox(cells):
        return min(r for r,c in cells), min(c for r,c in cells), max(r for r,c in cells), max(c for r,c in cells)

    heights = [max(bbox(cells)[2]-bbox(cells)[0]+1 for cells, _ in g) for g in groups]
    total_h = sum(heights) + len(groups) - 1
    y = h - total_h
    out = [[0] * w for _ in range(h)]
    for gi, group in enumerate(groups):
        x = 0
        for cells, color in group:
            r0, c0, r1, c1 = bbox(cells)
            for r, c in cells:
                out[y + r-r0][x + c-c0] = color
            x += c1-c0+2
        y += heights[gi] + 1
    return out
