    h, w = len(grid), len(grid[0])
    colors = sorted({v for row in grid for v in row if v != 0})

    def components(color):
        seen, found = set(), []
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or (r, c) in seen:
                    continue
                todo, cells = [(r, c)], []
                seen.add((r, c))
                while todo:
                    y, x = todo.pop()
                    cells.append((y, x))
                    for p in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                        py, px = p
                        if 0 <= py < h and 0 <= px < w and grid[py][px] == color and p not in seen:
                            seen.add(p)
                            todo.append(p)
                found.append(cells)
        return found

    # Extract objects; top pair and bottom pair are independently arranged by
    # their original left-to-right positions, with no spacer between shapes.
    groups = [[], []]
    for color in colors:
        objs = sorted(components(color), key=lambda cells: min(r for r, c in cells))
        for rank, cells in enumerate(objs):
            groups[rank].append((cells, color))

    def bounds(cells):
        return (min(r for r, c in cells), min(c for r, c in cells),
                max(r for r, c in cells), max(c for r, c in cells))

    for group in groups:
        group.sort(key=lambda item: min(c for r, c in item[0]))
    heights = [max(bounds(cells)[2] - bounds(cells)[0] + 1 for cells, _ in group) for group in groups]
    y = h - sum(heights) - 1
    out = [[0] * w for _ in range(h)]
    for i, group in enumerate(groups):
        x = 0
        for cells, color in group:
            r0, c0, r1, c1 = bounds(cells)
            for r, c in cells:
                out[y + r - r0][x + c - c0] = color
            x += c1 - c0 + 1
        y += heights[i] + 1
    return out
