    h, w = len(grid), len(grid[0])
    colors = sorted({v for row in grid for v in row if v})
    def objects(color):
        seen, result = set(), []
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or (r,c) in seen: continue
                todo=[(r,c)]; seen.add((r,c)); cells=[]
                while todo:
                    y,x=todo.pop(); cells.append((y,x))
                    for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                        if 0<=yy<h and 0<=xx<w and grid[yy][xx]==color and (yy,xx) not in seen:
                            seen.add((yy,xx)); todo.append((yy,xx))
                result.append(cells)
        return result
    def box(cells):
        return min(r for r,c in cells),min(c for r,c in cells),max(r for r,c in cells),max(c for r,c in cells)
    pairs={c:objects(c) for c in colors}
    # Process each color as its own column; in each column, order the two
    # components by area, small above large. Columns ordered by color.
    out=[[0]*w for _ in range(h)]
    x=0
    for color in colors:
        pair=sorted(pairs[color],key=len)
        if len(pair)!=2: raise ValueError('expected two components')
        top,bottom=pair
        rt,ct,rt1,ct1=box(top); rb,cb,rb1,cb1=box(bottom)
        ht=rt1-rt+1; hb=rb1-rb+1
        ytop=h-ht-hb-1
        ybottom=h-hb
        for r,c in top: out[ytop+r-rt][x+c-ct]=color
        for r,c in bottom: out[ybottom+r-rb][x+c-cb]=color
        x+=max(ct1-ct+1,cb1-cb+1)+1
    return out
