    h, w = len(grid), len(grid[0])
    colors = sorted({v for row in grid for v in row if v})

    def components(color):
        seen, result = set(), []
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or (r, c) in seen:
                    continue
                seen.add((r, c))
                stack, cells = [(r, c)], []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                        if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy, xx) not in seen:
                            seen.add((yy, xx))
                            stack.append((yy, xx))
                result.append(cells)
        return result

    def bounds(cells):
        return (min(r for r, c in cells), min(c for r, c in cells),
                max(r for r, c in cells), max(c for r, c in cells))

    out = [[0] * w for _ in range(h)]
    x = 0
    for color in colors:
        objs = sorted(components(color), key=len)
        small, large = objs[0], objs[1]
        r0, c0, r1, c1 = bounds(small)
        rs, cs, re, ce = bounds(large)
        sh, sw = r1 - r0 + 1, c1 - c0 + 1
        lh, lw = re - rs + 1, ce - cs + 1
        ysmall = h - (sh + 1 + lh)
        ylarge = h - lh
        for r, c in small:
            out[ysmall + r - r0][x + c - c0] = color
        for r, c in large:
            out[ylarge + r - rs][x + c - cs] = color
        x += max(sw, lw) + 1
    return out
